package ktanesolver.module.modded.regular.bases;import static org.assertj.core.api.Assertions.assertThat;import java.util.*;import org.junit.jupiter.api.Test;import ktanesolver.entity.*;import ktanesolver.enums.PortType;import ktanesolver.logic.*;import ktanesolver.module.modded.regular.bases.BasesInput.Operator;class BasesSolverTest{private final BasesSolver s=new BasesSolver();@Test void calculatesBasesConvertsAndAdds(){BombEntity b=bomb();var o=solve(b,new BasesInput("101","12",Operator.ADD));assertThat(o).isEqualTo(new BasesOutput("23",3,3,6,10,5));}@Test void usesTenWithoutModuloAndAbsoluteSubtraction(){assertThat(BasesSolver.base(10)).isEqualTo(10);BombEntity b=bomb();var o=solve(b,new BasesInput("1","20",Operator.SUBTRACT));assertThat(o.answer()).isEqualTo("5");}@Test void rejectsDigitsOutsideBaseAndNonIntegralDivision(){BombEntity b=bomb();assertThat(s.solve(new RoundEntity(),b,new ModuleEntity(),new BasesInput("9","1",Operator.ADD))).isInstanceOf(SolveFailure.class);assertThat(s.solve(new RoundEntity(),b,new ModuleEntity(),new BasesInput("10","2",Operator.DIVIDE))).isInstanceOf(SolveFailure.class);}private BasesOutput solve(BombEntity b,BasesInput i){return((SolveSuccess<BasesOutput>)s.solve(new RoundEntity(),b,new ModuleEntity(),i)).output();}private BombEntity bomb(){BombEntity b=new BombEntity();b.setSerialNumber("A1B2C3");b.setIndicators(new HashMap<>(Map.of("SND",true,"FRQ",false,"IND",true)));b.replacePortPlates(List.of(Set.of(PortType.DVI),Set.of(PortType.SERIAL)));return b;}}
